import {flowCopy} from './flow-copy.js?v=5.10.0';
export const TONTV_URL='https://t.me/TontvOfficialChannel';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tvIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="6" width="18" height="13" rx="3"/><path d="m9 2 3 4 3-4m-5 9 5 3-5 3Z"/></svg>';
export const waitingOrder=(orders,sessionId)=>sessionId?orders.filter(o=>o.sessionId===sessionId&&['pending','accepted','preparing','ready'].includes(o.status)).at(-1)||null:null;
export function tontvLink(lang){return `<a class="tontv-link" href="${TONTV_URL}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${tvIcon}<span>${esc(flowCopy(lang).tvOpen)}</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></a>`;}
export function loungeMarkup(lang,{mark='',ready=false,compact=false}={}){const c=flowCopy(lang);return `<section class="waiting-lounge ${compact?'compact':''}" aria-label="${esc(c.waitingTitle)}"><div class="lounge-heading">${mark}<div><small>RAMI × TonTV</small><h3>${esc(c.waitingTitle)}</h3></div></div><p>${esc(ready?c.waitingReady:c.waitingInvite)}</p>${tontvLink(lang)}<small class="lounge-terms">${esc(c.tvNote)}</small><small class="lounge-return">${esc(c.tvReturn)}</small>${compact?'':`<div class="lounge-topics">${[['wait-menu','talkMenu'],['wait-shop','talkShop'],['wait-status','talkStatus']].map(([action,key])=>`<button type="button" class="button" data-intent="${action}">${esc(c[key])}</button>`).join('')}</div><small class="lounge-terms">${esc(c.waitingNote)}</small>`}</section>`;}
export function waitingIntent(text){const s=String(text).trim().toLowerCase();return /^(기다리는 동안 (뭘|무엇을) 할까요\??|what can i do while waiting\??|tôi có thể làm gì trong lúc chờ\??|等待时可以做什么[？?]?|待っている間、何ができますか[？?]?|apa yang bisa saya lakukan sambil menunggu\??|इंतज़ार में मैं क्या कर सकता हूँ\??|ខ្ញុំអាចធ្វើអ្វីពេលរង់ចាំ\??|ຂ້ອຍເຮັດຫຍັງໄດ້ລະຫວ່າງລໍຖ້າ\??|tontv|톤티비)$/.test(s)?'waiting':null;}
